"""
Evaluation harness for cadrega.

Runs the cadrega binary (static analysis + LLM analysis, via --json) against
every skill listed in a manifest file, compares the reported verdicts against
the expected label, and prints a confusion matrix / precision / recall / F1
for both the static analyzer and the LLM analyzer.

Manifest format (CSV, header required):

    path,label
    skills/benign/summarizer.md,benign
    skills/malicious/exfil-via-base64.md,malicious

`path` is resolved relative to the manifest's own directory if it is not
absolute. `label` must be "benign" or "malicious" (case-insensitive).

Usage:
    python scripts/eval_skills.py \\
        --manifest skills_manifest.csv \\
        --binary ./cadrega \\
        --provider ollama --model llama3.1 \\
        --output results.json
"""

import argparse
import concurrent.futures
import csv
import json
import subprocess
import sys
from dataclasses import asdict, dataclass, field
from pathlib import Path

VALID_LABELS = {"benign", "malicious"}
VALID_VERDICTS = {"SAFE", "MALICIOUS", "SUSPICIOUS"}


@dataclass
class ManifestEntry:
    path: Path
    label: str


@dataclass
class SampleResult:
    path: str
    label: str
    static_verdict: str | None = None
    llm_verdict: str | None = None
    static_findings_count: int = 0
    llm_findings_count: int = 0
    error: str | None = None


@dataclass
class ConfusionMatrix:
    tp: int = 0
    fn: int = 0
    tn: int = 0
    fp: int = 0
    verdict_counts: dict = field(default_factory=dict)

    def record(self, label: str, verdict: str) -> None:
        self.verdict_counts[verdict] = self.verdict_counts.get(verdict, 0) + 1
        flagged = verdict != "SAFE"
        if label == "malicious":
            if flagged:
                self.tp += 1
            else:
                self.fn += 1
        else:
            if flagged:
                self.fp += 1
            else:
                self.tn += 1

    def precision(self) -> float:
        denom = self.tp + self.fp
        return self.tp / denom if denom else 0.0

    def recall(self) -> float:
        denom = self.tp + self.fn
        return self.tp / denom if denom else 0.0

    def f1(self) -> float:
        p, r = self.precision(), self.recall()
        return 2 * p * r / (p + r) if (p + r) else 0.0


def load_manifest(manifest_path: Path) -> list[ManifestEntry]:
    entries = []
    base_dir = manifest_path.parent

    with open(manifest_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None or {"path", "label"} - set(reader.fieldnames):
            raise ValueError("manifest must have 'path' and 'label' columns")

        for row_num, row in enumerate(reader, start=2):
            raw_path = row["path"].strip()
            label = row["label"].strip().lower()
            if not raw_path:
                continue
            if label not in VALID_LABELS:
                raise ValueError(
                    f"manifest row {row_num}: invalid label {label!r} "
                    f"(must be one of {sorted(VALID_LABELS)})"
                )
            path = Path(raw_path)
            if not path.is_absolute():
                path = base_dir / path
            entries.append(ManifestEntry(path=path, label=label))

    return entries


def run_cadrega(
    binary: str, skill_path: Path, args: argparse.Namespace, timeout: float
) -> SampleResult:
    result = SampleResult(path=str(skill_path), label="")  # label filled in by caller

    cmd = [
        binary,
        "--json",
        "--provider",
        args.provider,
        "--model",
        args.model,
    ]
    if args.provider == "ollama":
        cmd += [
            "--address",
            args.address,
            "--port",
            str(args.port),
            "--num-ctx",
            str(args.num_ctx),
        ]
        if args.think:
            cmd.append("--think")
        if args.unload_model:
            cmd.append("--unload-model")
    cmd.append(str(skill_path))

    try:
        print(cmd)
        proc = subprocess.run(
            cmd, capture_output=True, text=True, timeout=timeout, check=False
        )
    except subprocess.TimeoutExpired:
        result.error = f"timed out after {timeout}s"
        return result

    if proc.returncode != 0:
        result.error = (
            f"exit {proc.returncode}: {proc.stderr.strip() or proc.stdout.strip()}"
        )
        return result

    try:
        payload = json.loads(proc.stdout)
    except json.JSONDecodeError as e:
        result.error = f"invalid JSON output: {e}"
        return result

    result.static_verdict = payload.get("StaticVerdict")
    result.llm_verdict = payload.get("llmVerdict")
    result.static_findings_count = len(payload.get("staticFindings") or [])
    result.llm_findings_count = len(payload.get("llmFindings") or [])
    return result


def evaluate(
    entry: ManifestEntry, binary: str, args: argparse.Namespace, timeout: float
) -> SampleResult:
    result = run_cadrega(binary, entry.path, args, timeout)
    result.path = str(entry.path)
    result.label = entry.label
    return result


def print_matrix(title: str, cm: ConfusionMatrix, total_errors: int) -> None:
    print(f"\n{title}")
    print(f"  TP={cm.tp}  FN={cm.fn}  TN={cm.tn}  FP={cm.fp}  (errors={total_errors})")
    print(
        f"  precision={cm.precision():.3f}  recall={cm.recall():.3f}  f1={cm.f1():.3f}"
    )
    print(f"  verdict distribution: {cm.verdict_counts}")


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--manifest", required=True, type=Path, help="CSV manifest of skill,label pairs"
    )
    parser.add_argument(
        "--binary", default="./cadrega", help="path to the cadrega binary"
    )
    parser.add_argument(
        "--provider", required=True, choices=["ollama", "anthropic", "openai"]
    )
    parser.add_argument("--model", required=True)
    parser.add_argument("--address", default="localhost", help="Ollama server address")
    parser.add_argument("--port", type=int, default=11434, help="Ollama server port")
    parser.add_argument(
        "--think", action="store_true", help="enable Ollama thinking mode"
    )
    parser.add_argument(
        "--num-ctx", type=int, default=8192, help="Ollama context window size"
    )
    parser.add_argument(
        "--unload-model",
        action="store_true",
        help="unload the Ollama model after analysis",
    )
    parser.add_argument(
        "--timeout", type=float, default=180.0, help="per-sample timeout in seconds"
    )
    parser.add_argument(
        "--workers", type=int, default=1, help="number of samples to run concurrently"
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=Path("results.json"),
        help="where to write per-sample results",
    )
    args = parser.parse_args()

    try:
        entries = load_manifest(args.manifest)
    except (OSError, ValueError) as e:
        print(f"error: {e}", file=sys.stderr)
        return 1

    if not entries:
        print("error: manifest is empty", file=sys.stderr)
        return 1

    results: list[SampleResult] = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
        futures = {
            pool.submit(evaluate, entry, args.binary, args, args.timeout): entry
            for entry in entries
        }
        for i, future in enumerate(concurrent.futures.as_completed(futures), start=1):
            entry = futures[future]
            result = future.result()
            results.append(result)
            status = (
                "ERROR"
                if result.error
                else f"static={result.static_verdict} llm={result.llm_verdict}"
            )
            print(result.error)
            print(f"[{i}/{len(entries)}] {entry.label:9s} {entry.path}  ->  {status}")

    args.output.write_text(json.dumps([asdict(r) for r in results], indent=2))

    static_cm = ConfusionMatrix()
    llm_cm = ConfusionMatrix()
    static_errors = llm_errors = 0

    for r in results:
        if r.error:
            static_errors += 1
            llm_errors += 1
            continue
        if r.static_verdict in VALID_VERDICTS:
            static_cm.record(r.label, r.static_verdict)
        else:
            static_errors += 1
        if r.llm_verdict in VALID_VERDICTS:
            llm_cm.record(r.label, r.llm_verdict)
        else:
            llm_errors += 1

    print_matrix("Static analysis", static_cm, static_errors)
    print_matrix("LLM analysis", llm_cm, llm_errors)
    print(f"\nDetailed results written to {args.output}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
